def documents_to_knowledge_bases(apps, schema_editor):
    """v1 scoped documents by assistant_id; v2 uses knowledge bases. One KB per old assistant id."""
    KnowledgeBase = apps.get_model("hello_guy_ai", "KnowledgeBase")
    Document = apps.get_model("hello_guy_ai", "Document")
    slugs = set(Document.objects.exclude(assistant_id="").values_list("assistant_id", flat=True)) | {"hello_guy"}
    for slug in slugs:
        kb, _ = KnowledgeBase.objects.get_or_create(slug=slug, defaults={"name": slug.replace("_", " ").title()})
        # Vectors live in a new Milvus collection (v2 schema): mark for re-ingest (manage.py hello_guy_reindex).
        Document.objects.filter(assistant_id=slug).update(knowledge_base=kb, status="pending")


Migration.operations.append(migrations.RunPython(documents_to_knowledge_bases, migrations.RunPython.noop))
